27	const PROCESSING_FEE = 5;
28	
29	const BASE_PREMIUMS: Record<string, number> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	const FIRST_INSURANCE_PERCENT = 10;
39	
40	// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
41	// Math.ceil turns the drift into a whole extra gold piece. The spec requires
42	// intermediates to stay exact, so every percentage goes through here.
43	const PERCENT_WHOLE = 100;
44	
45	const percentOf = (amount: number, percent: number): number =>
46	  (amount * percent) / PERCENT_WHOLE;
47	
48	// Rounding always favours MHPCO: premiums round up, payouts round down.
49	const roundPremium = (amount: number): number => Math.ceil(amount);
50	
51	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
52	
53	const BLOCK_SIZE = 3;
54	const BLOCK_BASE_PREMIUM = 60;
55	
56	const countByType = (items: Item[]): Map<string, number> => {
57	  const counts = new Map<string, number>();
58	  for (const item of items) {
59	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
60	  }
61	  return counts;
62	};
63	
64	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
65	
66	const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);
67	
68	// Exactly 3 alike components are priced as a single block; everything else is
69	// priced per item. The block is only offered on components, never main items.
70	const groupBasePremiumOf = (type: string, count: number): number =>
71	  isComponent(type) && count === BLOCK_SIZE
72	    ? BLOCK_BASE_PREMIUM
73	    : count * basePremiumOfType(type);
74	
75	// The policy base premium is the sum of the base premiums of each group of
76	// alike items.
77	const policyBasePremiumOf = (items: Item[]): number =>
78	  [...countByType(items)].reduce(
79	    (total, [type, count]) => total + groupBasePremiumOf(type, count),
80	    0,
81	  );
82	
83	const quoteStep = (step: Step): QuoteResult => {
84	  const basePremium = policyBasePremiumOf(step.items);
85	  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
86	
87	  return {
88	    premium: roundPremium(
89	      basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
90	    ),
91	  };
92	};
93	
94	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
95	  results: scenario.steps.map(quoteStep),
96	});
